// ============================================================
// Keystone PT Script  -  Generated by Keystone Automation
//
// HOW TO USE
//   1. Open Packet Tracer
//   2. Place ONE seed device on the canvas for each type below:
//        - One 2911  (router)
//        - One 2960  (switch)
//        - One Server-PT  (server)
//        - One PC-PT  (pc)
//   3. Extensions  ->  Scripting  ->  Edit File Script Module
//   4. Load this file and click  Run
//   5. Manually cable the connections shown in the console output
//   6. Delete the original seed device(s) from the canvas
//   7. File  ->  Save As  ->  your_lab.pkt
//
// Topology: 6 device(s), 0 connection(s)
// ============================================================

function main()
{
    dprint("=== KEYSTONE TOPOLOGY BUILDER ===");
    dprint("");

    try {

        var network    = ipc.network();
        var activeFile = ipc.appWindow().getActiveFile();

        dprint("Seed devices on canvas: " + network.getDeviceCount());

        // ===== PHASE 1: LOCATE SEED DEVICES =====
        dprint("[1/4] Locating seed devices...");
        var seeds = {};
        for (var i = 0; i < network.getDeviceCount(); i++) {
            var d     = network.getDeviceAt(i);
            var model = d.getModel();
            if (!seeds[model]) {
                seeds[model] = d;
                dprint("  OK  Found seed: " + model + " (" + d.getName() + ")");
            }
        }

        if (!seeds["2911"]) {
            dprint("  ERR  Missing seed: 2911");
            dprint("       Add one router (2911) to the canvas and re-run.");
            return;
        }
        if (!seeds["2960"]) {
            dprint("  ERR  Missing seed: 2960");
            dprint("       Add one switch (2960) to the canvas and re-run.");
            return;
        }
        if (!seeds["Server-PT"]) {
            dprint("  ERR  Missing seed: Server-PT");
            dprint("       Add one server (Server-PT) to the canvas and re-run.");
            return;
        }
        if (!seeds["PC-PT"]) {
            dprint("  ERR  Missing seed: PC-PT");
            dprint("       Add one pc (PC-PT) to the canvas and re-run.");
            return;
        }

        // ===== PHASE 2: CREATE DEVICES =====
        dprint("[2/4] Creating devices...");
        var devs = {};

        // --- ISP-GATEWAY ---
        activeFile.duplicateDevice(seeds["2911"]);
        var dev_ISP_GATEWAY = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_ISP_GATEWAY.moveToLocationCentered(120, 120);
        devs["ISP-GATEWAY"] = dev_ISP_GATEWAY;
        dprint("  +  ISP-GATEWAY at (120, 120)");
        java.lang.Thread.sleep(300);

        // --- ENTERPRISE-CORE ---
        activeFile.duplicateDevice(seeds["2911"]);
        var dev_ENTERPRISE_CORE = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_ENTERPRISE_CORE.moveToLocationCentered(340, 120);
        devs["ENTERPRISE-CORE"] = dev_ENTERPRISE_CORE;
        dprint("  +  ENTERPRISE-CORE at (340, 120)");
        java.lang.Thread.sleep(300);

        // --- DIST-SWITCH ---
        activeFile.duplicateDevice(seeds["2960"]);
        var dev_DIST_SWITCH = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_DIST_SWITCH.moveToLocationCentered(560, 120);
        devs["DIST-SWITCH"] = dev_DIST_SWITCH;
        dprint("  +  DIST-SWITCH at (560, 120)");
        java.lang.Thread.sleep(300);

        // --- DHCP-SERVER ---
        activeFile.duplicateDevice(seeds["Server-PT"]);
        var dev_DHCP_SERVER = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_DHCP_SERVER.moveToLocationCentered(780, 120);
        devs["DHCP-SERVER"] = dev_DHCP_SERVER;
        dprint("  +  DHCP-SERVER at (780, 120)");
        java.lang.Thread.sleep(300);

        // --- CLIENT-PC1 ---
        activeFile.duplicateDevice(seeds["PC-PT"]);
        var dev_CLIENT_PC1 = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_CLIENT_PC1.moveToLocationCentered(1000, 120);
        devs["CLIENT-PC1"] = dev_CLIENT_PC1;
        dprint("  +  CLIENT-PC1 at (1000, 120)");
        java.lang.Thread.sleep(300);

        // --- CLIENT-PC2 ---
        activeFile.duplicateDevice(seeds["PC-PT"]);
        var dev_CLIENT_PC2 = network.getDeviceAt(network.getDeviceCount() - 1);
        dev_CLIENT_PC2.moveToLocationCentered(120, 340);
        devs["CLIENT-PC2"] = dev_CLIENT_PC2;
        dprint("  +  CLIENT-PC2 at (120, 340)");
        java.lang.Thread.sleep(300);

        // ===== PHASE 3: CONNECTIONS (manual cabling required) =====
        dprint("[3/4] Connections to cable manually:");
        dprint("  (no connections defined in topology)");

        // ===== PHASE 4: CONFIGURE DEVICES =====
        dprint("[4/4] Configuring devices (this may take a moment)...");

        dprint("  >> ISP-GATEWAY");
        configureDevice(devs["ISP-GATEWAY"], ["enable", "configure terminal", "hostname ISP-GATEWAY", "interface GigabitEthernet0/0/0", " description ISP uplink", " ip address 203.0.113.1 255.255.255.0", " no shutdown", " exit", "interface GigabitEthernet0/0/1", " description To Enterprise", " ip address 192.168.1.1 255.255.255.0", " no shutdown", " exit", "router bgp 65000", " bgp router-id 203.0.113.1", " neighbor 192.168.1.2 remote-as 65100", " neighbor 192.168.1.2 description Enterprise BGP Peer", " exit", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("  >> ENTERPRISE-CORE");
        configureDevice(devs["ENTERPRISE-CORE"], ["enable", "configure terminal", "hostname ENTERPRISE-CORE", "interface GigabitEthernet0/0/0", " description To ISP", " ip address 192.168.1.2 255.255.255.0", " no shutdown", " exit", "interface GigabitEthernet0/0/1", " description To Distribution", " ip address 10.0.1.1 255.255.255.0", " no shutdown", " exit", "interface GigabitEthernet0/0/2", " description To Services", " ip address 10.0.2.1 255.255.255.0", " no shutdown", " exit", "router ospf 1", " router-id 10.0.1.1", " network 10.0.1.0 0.0.0.255 area 0", " network 10.0.2.0 0.0.0.255 area 0", " exit", "router bgp 65100", " bgp router-id 10.0.1.1", " neighbor 192.168.1.1 remote-as 65000", " neighbor 192.168.1.1 description ISP peer", " exit", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("  >> DIST-SWITCH");
        configureDevice(devs["DIST-SWITCH"], ["enable", "configure terminal", "hostname DIST-SWITCH", "interface GigabitEthernet0/0/0", " description Uplink to Core", " ip address 10.0.1.2 255.255.255.0", " no shutdown", " exit", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("  >> DHCP-SERVER");
        configureDevice(devs["DHCP-SERVER"], ["enable", "configure terminal", "hostname DHCP-SERVER", "interface GigabitEthernet0/0/0", " description DHCP service", " ip address 10.0.2.10 255.255.255.0", " no shutdown", " exit", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("  >> CLIENT-PC1");
        configureDevice(devs["CLIENT-PC1"], ["enable", "configure terminal", "hostname CLIENT-PC1", "interface FastEthernet0", " description Office workstation", " ip address 10.0.1.100 255.255.255.0", " no shutdown", " exit", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("  >> CLIENT-PC2");
        configureDevice(devs["CLIENT-PC2"], ["enable", "configure terminal", "hostname CLIENT-PC2", "interface FastEthernet0", " description Office workstation", " ip address 10.0.1.101 255.255.255.0", " no shutdown", " exit", "end", "write memory"]);
        java.lang.Thread.sleep(500);

        dprint("");
        dprint("=== TOPOLOGY COMPLETE ===");
        dprint("  Devices created : 6");
        dprint("  Connections     : 0 (see above for cabling)");
        dprint("");
        dprint("Next steps:");
        dprint("  1. Cable the connections listed above");
        dprint("  2. Delete the original seed device(s)");
        dprint("  3. File -> Save As -> your_lab.pkt");

    } catch(e) {
        dprint("FATAL ERROR: " + e.message);
        dprint(e.stack);
    }
}


// ============================================================
// Helper: send a list of IOS CLI commands to a device
// ============================================================
function configureDevice(device, commands)
{
    try {
        var cli = device.getCommandLine();
        if (cli == null) {
            dprint("  WARN  No CLI available for " + device.getName());
            return;
        }

        // Dismiss the initial configuration dialog if it appears
        var initialOut = cli.getOutput();
        if (initialOut.indexOf("initial configuration dialog") > -1) {
            cli.enterCommand("no");
            java.lang.Thread.sleep(500);
        }

        // Send each command with a short delay
        for (var i = 0; i < commands.length; i++) {
            cli.enterCommand(commands[i]);
            java.lang.Thread.sleep(100);
        }

        dprint("  OK  " + device.getName());

    } catch(e) {
        dprint("  ERR  " + device.getName() + ": " + e.message);
    }
}


function cleanUp()
{
    dprint("Script cleanup complete.");
}
